import itertools

# Verify: triangle-free
def has_triangle(edges, n):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for i in range(n):
        for j in range(i+1, n):
            if adj[i][j]:
                for k in range(j+1, n):
                    if adj[i][k] and adj[j][k]:
                        return True, (i,j,k)
    return False, None

# Verify: maximal (adding any non-edge creates a triangle)
def is_maximal_triangle_free(edges, n):
    edge_set = set(edges)
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True

    for u in range(n):
        for v in range(u+1, n):
            if not adj[u][v]:
                # Check if adding (u,v) creates a triangle
                creates_triangle = False
                for w in range(n):
                    if w != u and w != v and adj[u][w] and adj[v][w]:
                        creates_triangle = True
                        break
                if not creates_triangle:
                    return False, (u, v)
    return True, None

